# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÜLKEMİZİN KOMŞULARIYLA EKONOMİK, ULAŞIM VE KÜLTÜREL İLİŞKİLERİ (SB.5.2.4)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ekonomik ve Ticari İlişkiler</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• İhracat (Dış satım): Makine, taşıt,</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">beyaz eşya, tekstil, gıda, demir-çelik</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• İthalat (Dış alım): Petrol, doğal gaz,</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" fill="#1e3a8a">ham madde ve sanayi ürünleri</text>\n  <text x="125" y="190" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Sınır kapıları (Kapıkule, Habur,</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Sarp, Gürbulak) ticaretin kapısıdır.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Enerji ve Ulaşım Koridoru</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#78350f">• TANAP ve Bakü-Tiflis-Ceyhan</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#78350f">boru hatları (Azerbaycan-Gürcistan)</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11.5" fill="#78350f">• Bakü-Tiflis-Kars Demiryolu</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#78350f">(Demir İpek Yolu bağlantısı)</text>\n  <text x="350" y="190" text-anchor="middle" font-size="11.5" fill="#78350f">• Asya ile Avrupa arasında</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">stratejik enerji ve ulaşım köprüsü</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kültürel ve İnsani Bağlar</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Ortak tarih, mutfak, müzik ve</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">gelenekler (Nevruz, bayramlar)</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11.5" fill="#14532d">• Turizm, eğitim ve öğrenci değişimi</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" fill="#14532d">• Doğal afetlerde (deprem, yangın)</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11.5" fill="#14532d">karşılıklı insani yardımlaşma</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">«Yurtta sulh, cihanda sulh» ilkesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. ÖĞRENME ALANINA GİRİŞ: ORTAK MİRAS KAVRAMI VE TÜRLERİ (SB.5.3.1)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Somut Kültürel ve Doğal Miras</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• Elle tutulup gözle görülebilen tarihî yapılar,</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11.5" fill="#831843">antik kentler, eserler ve doğal güzelliklerdir.</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11.5" fill="#831843">• Taşınmaz Miras: Göbeklitepe, Efes, Selimiye</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11.5" fill="#831843">Camii, Divriği Ulu Camii, Pamukkale, Kapadokya</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11.5" fill="#831843">• Taşınabilir Miras: Müzelerdeki sikkeler, çiniler,</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">el yazmaları, halılar ve arkeolojik buluntular</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Somut Olmayan Kültürel Miras</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">• Kuşaktan kuşağa sözlü ve uygulamalı aktarılan</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">gelenekler, sanatlar, bilgi ve kutlamalardır.</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">• Gösteri ve Sözlü Kültür: Karagöz, Meddahlık,</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">Âşıklık geleneği, Dede Korkut hikâyeleri</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11.5" fill="#155e75">• Gelenek ve Sanatlar: Ebru sanatı, Çini sanatı,</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Türk kahvesi kültürü, Nevruz, Hıdırellez, Kırkpınar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAŞADIĞIMIZ İLDEKİ ORTAK MİRAS ÖGELERİNİ TANIMA VE KORUMA</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Ortak Mirasın Önemi ve Vatandaşlık Sorumluluğumuz (SB.5.3.1)</text>\n  <text x="55" y="104" font-size="12" fill="#4c1d95">• UNESCO (Birleşmiş Milletler Eğitim, Bilim ve Kültür Örgütü): İnsanlığın ortak mirası</text>\n  <text x="70" y="124" font-size="12" fill="#1e293b">sayılan doğal ve kültürel varlıkları Dünya Miras Listesi\'ne alarak uluslararası düzeyde korur.</text>\n  <text x="55" y="152" font-size="12" fill="#4c1d95">• Yaşadığımız İldeki Miras Ögeleri: İlimizdeki kaleler, camiler, hanlar, köprüler, müzeler,</text>\n  <text x="70" y="172" font-size="12" fill="#1e293b">yöresel el sanatları, halk oyunları ve geleneksel yemekler geçmişle gelecek arasındaki köprüdür.</text>\n  <text x="55" y="200" font-size="12" fill="#4c1d95">• Koruma Bilinci: Tarihî eserlere zarar vermemek, müzeleri ziyaret etmek ve kültürel</text>\n  <text x="70" y="220" font-size="12" fill="#1e293b">değerlerimizi tanıtarak gelecek kuşaklara bozulmadan aktarmak hepimizin ortak görevidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
